请你将下面代码整理到/home/wsb/openvela_0error/contest2026_059_0error/boards/sg2000/milkv_duos/src下的一个文件中，名为gc2083_test.c，i2c相关的不要了，我们只测试mclk是否正确产生
#include <nuttx/arch.h>

/* ====== 寄存器地址 ====== */
#define TOP_BASE           0x03000000
#define PINMUX_BASE        (TOP_BASE + 0x1000)   /* 0x03001000 */
#define CLKGEN_BASE        (TOP_BASE + 0x2000)   /* 0x03002000 */
#define PLL_G2_BASE        (TOP_BASE + 0x2800)   /* 0x03002800 */

/* Pinmux 寄存器 */
#define REG_FUNCSEL_CAM_MCLK0  (PINMUX_BASE + 0x000)  /* 0x03001000 */
#define REG_FUNCSEL_PC17       (PINMUX_BASE + 0x1A8)  /* 0x030011A8 */

/* 时钟寄存器 */
#define REG_CLK_CAM0_SRC_DIV   (CLKGEN_BASE + 0x8C0)  /* 0x030028C0 */
#define REG_CLK_EN_2           (CLKGEN_BASE + 0x008)   /* 0x03002008 */

/* GPIO Port C (PC17) */
#define GPIO_PORTC_BASE        0x03022000
#define GPIO_SWPORTA_DR        (GPIO_PORTC_BASE + 0x000)  /* 数据寄存器 */
#define GPIO_SWPORTA_DDR       (GPIO_PORTC_BASE + 0x400)  /* 方向寄存器 */


/* ====== Step 1: Pinmux ====== */
void sg2002_pinmux_init(void)
{
    uint32_t val;

    /*
     * CAM_MCLK0 → 设为原生 MCLK 功能 (func=0)
     * 寄存器 0x03001000, [2:0] = 0
     */
    val = getreg32(REG_FUNCSEL_CAM_MCLK0);
    val &= ~0x7;            /* 清除 [2:0] */
    val |= 0;               /* 0 = CAM_MCLK0 原生功能 */
    putreg32(val, REG_FUNCSEL_CAM_MCLK0);

    /*
     * PC17 (XGPIOC_17) → 设为 GPIO 模式 (func=3)
     * 用于控制 GC2083 的 RESET# 引脚
     * 寄存器 0x030011A8, [2:0] = 3
     */
    val = getreg32(REG_FUNCSEL_PC17);
    val &= ~0x7;            /* 清除 [2:0] */
    val |= 3;               /* 3 = XGPIOC_17 GPIO 模式 */
    putreg32(val, REG_FUNCSEL_PC17);
}


/* ====== Step 2: GPIO 复位传感器 ====== */
void sg2002_sensor_reset(void)
{
    uint32_t val;

    /* PC17 设为输出 */
    val = getreg32(GPIO_SWPORTA_DDR);
    val |= (1 << 17);
    putreg32(val, GPIO_SWPORTA_DDR);

    /* PC17 = LOW (复位生效) */
    val = getreg32(GPIO_SWPORTA_DR);
    val &= ~(1 << 17);
    putreg32(val, GPIO_SWPORTA_DR);
    usleep(1000);

    /* PC17 = HIGH (释放复位) */
    val = getreg32(GPIO_SWPORTA_DR);
    val |= (1 << 17);
    putreg32(val, GPIO_SWPORTA_DR);
    usleep(10000);  /* 等传感器稳定 */
}


/* ====== Step 3: MCLK 时钟配置 ====== */
void sg2002_cam0_mclk_enable_24m(void)
{
    uint32_t val;

    /*
     * CAM0PLL 已经由 FSBL 设为 1188 MHz，不需要动
     * 只需配置 clk_cam0 分频器:
     *   时钟源 = clk_cam0pll (1188 MHz)
     *   分频因子 = 49
     *   输出 = 1188 / 49 ≈ 24.24 MHz
     */

    /* 选择时钟源 clk_cam0pll (00), 分频 = 49 */
    val = getreg32(REG_CLK_CAM0_SRC_DIV);
    val &= ~(0x3 << 8);     /* 清除 CLK_SRC [9:8] */
    val |=  (0x0 << 8);     /* 00 = clk_cam0pll */
    val &= ~(0x3F << 16);   /* 清除 DIV [21:16] */
    val |=  (49 << 16);     /* 分频因子 49 */
    putreg32(val, REG_CLK_CAM0_SRC_DIV);

    /* 使能 clk_cam0 时钟门控 (bit 16) */
    val = getreg32(REG_CLK_EN_2);
    val |= (1 << 16);
    putreg32(val, REG_CLK_EN_2);

    up_udelay(100);  /* 等时钟稳定 */
}


/* ====== 完整 bringup ====== */
void gc2083_bringup(void)
{
    /* 1. Pinmux */
    sg2002_pinmux_init();

    /* 2. MCLK 24MHz */
    sg2002_cam0_mclk_enable_24m();
    usleep(10000);

    /* 3. 复位传感器 */
    sg2002_sensor_reset();

    /* 4. I2C 通信 (Duo256M 用 i2c1) */
    int fd = open("/dev/i2c-1", O_RDWR);
    ioctl(fd, I2C_SLAVE, 0x37);

    /* 5. 读芯片 ID 验证 */
    uint8_t id_h = gc2083_read_reg(fd, 0x03F0);
    uint8_t id_l = gc2083_read_reg(fd, 0x03F1);
    syslog(LOG_INFO, "GC2083 ID: 0x%02X%02X\n", id_h, id_l);
    /* 期望: 0x2083 */

    /* 6. 写初始化寄存器序列... */
}

